import re

from langfuse import Langfuse, observe

EMAIL = re.compile(r"[\w.-]+@[\w.-]+")


def mask_contact_details(*, data, **kwargs):
    if isinstance(data, str):
        return EMAIL.sub("[REMOVED EMAIL]", data)
    return data


langfuse = Langfuse(mask=mask_contact_details)


@observe()
def answer(user_email, question):
    prompt = "User " + user_email + " asks: " + question
    return call_model(prompt)
